(()=>{'use strict';
const C=window.FranklinAssistantCore,root=document.querySelector('[data-navigator-bot]');if(!C||!root)return;
const form=root.querySelector('form'),input=root.querySelector('[data-navigator-input]'),output=root.querySelector('[data-navigator-output]');if(!form||!input||!output)return;
const VERSION=C.VERSION,COMMUNITY='FRANKLIN_TN',DIR_MANIFEST='/data/discovery/manifest.json',DIR_SHA='d97640231d541f5a4f67ac26782806fc933237a39566e6e59561ea82e894e225';
let routePromise,dirPromise;
root.dataset.franklinAssistantV2='1';root.dataset.franklinAssistantVersion=VERSION;document.querySelector('meta[name="franklin-release"]')?.setAttribute('content',VERSION);
const lang=()=>String(document.documentElement.lang||'').toLowerCase().startsWith('es')?'es':'en',tx=(en,es)=>lang()==='es'?es:en;
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!=null)n.textContent=text;if(cls)n.className=cls;return n};
const safeWeb=v=>{try{const u=new URL(String(v||''));return /^https?:$/.test(u.protocol)&&!u.username&&!u.password&&u.hostname.includes('.')?u.href:''}catch{return''}};
const phone=v=>{const s=String(v||''),d=s.replace(/\D/g,'');return /^[+\d().\s-]{7,30}$/.test(s)&&d.length>=7?'tel:'+s.replace(/[^+\d]/g,''):''};
const email=v=>{const s=String(v||'');return /^[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,63}$/.test(s)?'mailto:'+s:''};
const trim=(v,n=230)=>{const s=String(v||'').replace(/\s+/g,' ').trim();return s.length<=n?s:s.slice(0,n-1).replace(/\s+\S*$/,'')+'…'};
const title=v=>String(v||'').replace(/\s*\|\s*Franklin Navigator\s*$/i,'').trim();
const hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(x=>x.toString(16).padStart(2,'0')).join('');
async function verified(url,expected,max,type='json'){if(!crypto?.subtle)throw Error('Secure source checking unavailable');const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),20000);try{const r=await fetch(url,{credentials:'omit',referrerPolicy:'no-referrer',cache:'no-cache',signal:ctl.signal});if(!r.ok)throw Error('Source unavailable');const declared=Number(r.headers.get('content-length')||0);if(declared>max)throw Error('Source too large');const b=await r.arrayBuffer();if(b.byteLength>max||await hash(b)!==expected)throw Error('Source changed');const text=new TextDecoder('utf-8',{fatal:true}).decode(b);return type==='json'?JSON.parse(text):text}finally{clearTimeout(timer)}}
async function routes(){if(!routePromise)routePromise=Promise.all(C.ROUTE_SHARDS.map(async([path,sha],i)=>{const d=await verified(path,sha,500000);if(d.schemaVersion!=='franklin.assistant-route-shard.v1'||d.community!==COMMUNITY||d.release!==VERSION||d.shard!==String(i).padStart(2,'0')||!Array.isArray(d.records)||d.records.length!==d.recordCount)throw Error('Wrong route shard');return d.records})).then(x=>x.flat()).then(x=>{if(x.length!==254)throw Error('Route count mismatch');return x}).catch(e=>{routePromise=undefined;throw e});return routePromise}
function decodeIndex(raw){if(!raw||raw.schemaVersion!=='franklin.discovery-index.v1'||raw.community!==COMMUNITY||!Array.isArray(raw.rows)||raw.rows.length!==raw.recordCount)throw Error('Wrong directory source');const d=(k,i)=>Array.isArray(raw[k])&&Number.isInteger(i)&&i>=0&&i<raw[k].length?String(raw[k][i]||''):'';return raw.rows.map(a=>({id:String(a[0]||''),name:String(a[1]||''),location:String(a[2]||''),category:d('categories',a[3]),type:d('types',a[4]),area:d('areas',a[5]),websiteHref:safeWeb(d('websites',a[6])),phoneHref:phone(a[7]),emailHref:email(a[8]),exact:a[10]===true})).filter(x=>x.id&&x.name)}
async function directory(){if(!dirPromise)dirPromise=(async()=>{const m=await verified(DIR_MANIFEST,DIR_SHA,64000);if(m.community!==COMMUNITY||m.schemaVersion!=='franklin.discovery-manifest.v1'||!m.index||m.recordCount!==19103)throw Error('Wrong directory manifest');const raw=await verified(m.index.file,m.index.sha256,12000000);const rows=decodeIndex(raw);if(rows.length!==m.recordCount)throw Error('Directory count mismatch');return rows})().catch(e=>{dirPromise=undefined;throw e});return dirPromise}
function link(label,href,primary=false){const a=el('a',label,'button'+(primary?' primary':''));a.href=href;if(/^https?:/i.test(href)){a.target='_blank';a.rel='noopener noreferrer';a.referrerPolicy='no-referrer'}return a}
function actions(items){const d=el('div',null,'actions');items.filter(x=>x&&x[1]).forEach((x,i)=>d.append(link(x[0],x[1],i===0)));return d}
const SPECIAL={
 emergency:{title:['Get urgent help now','Obtén ayuda urgente ahora'],text:['If someone may be in immediate danger, call 911 now. Franklin Navigator does not dispatch responders.','Si alguien puede estar en peligro inmediato, llama al 911 ahora. Franklin Navigator no envía servicios de emergencia.'],links:[['Call 911','tel:911'],['Emergency starting points','/community-help-center/#urgent-help']]},
 crisis:{title:['Mental-health or emotional crisis','Crisis de salud mental o emocional'],text:['Call or text 988 for crisis support. Use 911 for immediate danger.','Llame o envíe un mensaje al 988 para apoyo en crisis. Use el 911 si hay peligro inmediato.'],links:[['Call or text 988','tel:988'],['Health and safety resources','/health-safety/']]},
 billing:{title:['Manage membership or billing','Administrar membresía o facturación'],text:['Sign in to your existing membership account. You can manage the payment method or cancel renewal there. If a payment is still processing or you already paid, do not pay again.','Inicie sesión en su cuenta de membresía. Allí puede administrar el método de pago o cancelar la renovación. Si un pago sigue procesándose o ya pagó, no vuelva a pagar.'],links:[['Open membership status','/membership-status/'],['Member support','/member-support/']]},
 profile:{title:['Manage, correct or remove your profile','Administrar, corregir o eliminar su perfil'],text:['Find the correct public profile first. Factual corrections and removal requests are free; paying does not change factual accuracy or ordinary Directory ranking.','Primero busque el perfil público correcto. Las correcciones y solicitudes de eliminación son gratuitas; pagar no cambia la exactitud ni la clasificación ordinaria.'],links:[['Find or manage my profile','/claim-profile/'],['Free correction or removal','/corrections/']]},
 membership:{title:['Franklin Community Membership','Membresía Comunitaria de Franklin'],text:['Community Membership is the optional $35/year membership. Start by finding your profile and signing in or creating an account. Already a member? Use your existing account rather than paying again.','La Membresía Comunitaria es opcional y cuesta $35 al año. Empiece buscando su perfil e iniciando sesión o creando una cuenta. Si ya es miembro, use su cuenta existente.'],links:[['See membership and start','/membership-start/'],['Find my profile','/claim-profile/']]}
};
function renderSpecial(id){const s=SPECIAL[id];if(!s)return;const card=el('article',null,'navigator-result franklin-assistant-v2-answer');card.append(el('h3',s.title[lang()==='es'?1:0]),el('p',s.text[lang()==='es'?1:0]),actions(s.links.map(x=>[x[0],x[1]])));output.append(card)}
async function routeSummary(path){try{const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),8000);try{const r=await fetch(path,{credentials:'omit',referrerPolicy:'no-referrer',cache:'no-cache',signal:ctl.signal});if(!r.ok||!/text\/html/i.test(r.headers.get('content-type')||''))return'';const declared=Number(r.headers.get('content-length')||0);if(declared>600000)return'';const html=await r.text();if(html.length>600000)return'';const page=new DOMParser().parseFromString(html,'text/html');return trim(page.querySelector('meta[name="description"]')?.content||page.querySelector('main p')?.textContent||'',240)}finally{clearTimeout(timer)}}catch{return''}}
async function multiRoutes(records,raw){const ids=C.concepts(raw);if(ids.length<2)return C.rankRoutes(records,raw,lang(),4);const out=[],seen=new Set();for(const id of ids.slice(0,4)){const hit=C.rankRoutes(records,raw,lang(),1,id)[0];if(hit&&!seen.has(hit.rec.p)){seen.add(hit.rec.p);out.push(hit)}}for(const hit of C.rankRoutes(records,raw,lang(),4)){if(out.length>=4)break;if(!seen.has(hit.rec.p)){seen.add(hit.rec.p);out.push(hit)}}return out}
async function renderRoutes(hits,raw){if(!hits.length)return;const section=el('section',null,'franklin-assistant-v2-routes');section.append(el('h3',C.concepts(raw).length>1?tx('A Franklin plan for the parts of your question','Un plan de Franklin para las partes de su pregunta'):tx('Best Franklin next step','Mejor próximo paso en Franklin')));const first=hits[0].rec,card=el('article',null,'navigator-result');card.append(el('h4',title(first.t)));const s=await routeSummary(first.p);if(s)card.append(el('p',s));card.append(actions([[tx('Open this Franklin guide','Abrir esta guía de Franklin'),first.p]]));section.append(card);const extras=hits.slice(1,4);if(extras.length){section.append(el('p',tx('Also useful:','También puede ser útil:'),'fine-print'));const ul=el('ul',null,'franklin-assistant-related');extras.forEach(x=>{const li=el('li');li.append(link(title(x.rec.t),x.rec.p));ul.append(li)});section.append(ul)}output.append(section)}
function renderProfiles(hits,raw,contactOnly=false){if(!hits.length)return;const sec=el('section',null,'franklin-assistant-v2-profiles'),top=hits[0].row;sec.append(el('h3',contactOnly&&hits[0].score>=55?tx(`Contact details for ${top.name}`,`Datos de contacto de ${top.name}`):tx('Franklin-area matches','Coincidencias del área de Franklin')));if(!contactOnly)sec.append(el('p',tx('These are factual public-profile matches, not endorsements. Confirm services, credentials where relevant, price and availability directly.','Estas son coincidencias informativas, no recomendaciones. Confirme servicios, credenciales, precio y disponibilidad directamente.')));const grid=el('div',null,'franklin-assistant-profile-grid');hits.slice(0,contactOnly?1:3).forEach(({row})=>{const card=el('article',null,'franklin-assistant-profile-card');card.append(el('h4',row.name),el('p',[row.category||row.type,row.location||row.area].filter(Boolean).join(' · '),'franklin-assistant-profile-meta'));const a=[];a.push([tx('Open profile','Abrir perfil'),`/profiles/${encodeURIComponent(row.id)}/`]);if(row.phoneHref)a.push([tx('Call','Llamar'),row.phoneHref]);if(row.websiteHref)a.push([tx('Website','Sitio web'),row.websiteHref]);if(row.emailHref)a.push([tx('Email','Correo'),row.emailHref]);card.append(actions(a));grid.append(card)});sec.append(grid);if(!contactOnly)sec.append(link(tx('See all matching profiles','Ver todos los perfiles coincidentes'),'/directory/?q='+encodeURIComponent(C.serviceFor(raw)?.q||trim(raw,80))));output.append(sec)}
function appendLegacySave(raw){try{const legacy=window.FranklinR38Assistant;if(!legacy?.render||['emergency','crisis'].includes(C.mode(raw)))return;const tmp=document.createElement('div');legacy.render(tmp,raw);const save=tmp.querySelector('.r38-assistant-save');if(save){save.querySelector('h3')?.replaceChildren(document.createTextNode(tx('Keep these next steps','Guardar estos próximos pasos')));output.append(save)}}catch{}}
function fallback(raw){const h=el('h3',tx('I can still get you to a useful Franklin starting point.','Aún puedo llevarle a un punto de partida útil en Franklin.')),p=el('p',tx('I did not find one strong answer from the current Franklin guides or public profiles. Try a shorter service or organization name, or use the routes below.','No encontré una respuesta suficientemente clara. Pruebe un nombre de servicio u organización más corto o use las rutas siguientes.'));output.append(h,p,actions([[tx('Browse practical tasks','Explorar tareas prácticas'),'/get-it-done/'],[tx('Search Find Local','Buscar en Find Local'),'/directory/?q='+encodeURIComponent(trim(raw,80))],[tx('Open Help Center','Abrir Centro de ayuda'),'/community-help-center/']]))}
async function render(raw){output.hidden=false;output.replaceChildren();const q=C.norm(raw);if(!q){output.append(el('p',tx('Tell me what you need in a few words. I can search Franklin guides and local public profiles, then point you to the best next step.','Dígame lo que necesita. Puedo buscar guías de Franklin y perfiles públicos locales y llevarle al mejor próximo paso.')));return}const m=C.mode(raw);if(m==='emergency'||m==='crisis'){renderSpecial(m);output.focus();return}const wait=el('p',tx('Checking Franklin guides and local profiles…','Consultando guías de Franklin y perfiles locales…'),'fine-print');wait.setAttribute('role','status');output.append(wait);let rr=[];try{rr=await routes()}catch{}const routeHits=rr.length?await multiRoutes(rr,raw):[];const needDir=!!C.serviceFor(raw)||C.wantsContact(raw)||C.wantsLocal(raw)||!routeHits.length||routeHits[0]?.score<35;let dh=[];if(needDir){try{dh=C.rankDirectory(await directory(),raw,5)}catch{}}output.replaceChildren();if(['billing','profile','membership'].includes(m))renderSpecial(m);if(C.wantsContact(raw)&&dh.length)renderProfiles(dh,raw,true);if(routeHits.length)await renderRoutes(routeHits,raw);if(!C.wantsContact(raw)&&dh.length)renderProfiles(dh,raw,false);if(!routeHits.length&&!dh.length&&!['billing','profile','membership'].includes(m))fallback(raw);appendLegacySave(raw);output.append(el('p',tx('Your question stays in this browser. Franklin Assistant reads Franklin Navigator’s published guide index and public-profile index; it does not send your wording to a new AI service.','Su pregunta permanece en este navegador. Franklin Assistant consulta el índice publicado de guías y perfiles públicos; no envía sus palabras a un nuevo servicio de IA.'),'fine-print franklin-assistant-privacy'));output.focus();window.FranklinProductHealth?.record?.(dh.length?'assistant_v2_profiles':routeHits.length?'assistant_v2_routes':'assistant_v2_fallback')}
form.addEventListener('submit',e=>{e.preventDefault();e.stopImmediatePropagation();render(input.value)},true);
root.addEventListener('click',e=>{const b=e.target.closest('[data-navigator-example]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();input.value=b.dataset.navigatorExample||b.textContent;render(input.value)},true);
const oldVoice=root.querySelector('[data-navigator-voice]');if(oldVoice){const v=oldVoice.cloneNode(true);oldVoice.replaceWith(v);const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(SR){v.hidden=false;let listening=false;const rec=new SR();rec.interimResults=false;rec.continuous=false;rec.maxAlternatives=1;const status=root.querySelector('[data-navigator-voice-status]'),set=m=>{if(status)status.textContent=m};rec.addEventListener('start',()=>{listening=true;v.textContent=tx('Listening…','Escuchando…');set(tx('Listening. Speak a short Franklin question or goal.','Escuchando. Diga una pregunta u objetivo breve.'))});rec.addEventListener('result',e=>{const t=String(e.results?.[0]?.[0]?.transcript||'').trim();if(t){input.value=t;render(t)}set(tx('Voice input captured.','Voz recibida.'))});rec.addEventListener('end',()=>{listening=false;v.textContent=tx('🎙 Speak','🎙 Hablar')});rec.addEventListener('error',()=>set(tx('Voice input did not finish. You can keep typing.','La entrada de voz no terminó. Puede seguir escribiendo.')));v.addEventListener('click',()=>{if(listening){rec.stop();return}rec.lang=lang()==='es'?'es-US':'en-US';try{rec.start()}catch{}})}else v.hidden=true}
window.addEventListener('franklinlanguagechange',()=>{if(input.value.trim()&&!output.hidden)render(input.value)});
window.FranklinAssistantV2=Object.freeze({version:VERSION,render});
})();